css:
@import url("https://fonts.googleapis.com/css2?family=Epilogue:wght@300;400;600;800&display=swap");
:root{--k:#1A1A1A;--cn:#F2F1EE;--mu:#77756F;--ln:#D9D7D1;--ac:#B5542C;--f:"Epilogue",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:var(--f);font-size:17px;line-height:1.65;color:#2A2A2A;background:var(--cn);font-weight:300}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{margin:0;font-weight:800;line-height:1;color:var(--k);letter-spacing:-.03em}
.wrap{max-width:1320px;margin:0 auto;padding:0 28px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--ac);color:#fff;padding:8px;z-index:99}:focus-visible{outline:2px solid var(--ac);outline-offset:3px}
.hd{border-bottom:1px solid var(--ln)}.nav{display:flex;justify-content:space-between;align-items:center;height:78px}
.logo{font-weight:800;font-size:20px;letter-spacing:.14em;text-decoration:none;color:var(--k)}.logo span{color:var(--ac)}
.menu{display:flex;gap:30px;list-style:none;margin:0;padding:0;font-weight:400;font-size:15px}.menu a{text-decoration:none}.menu a:hover{color:var(--ac)}
.burger{display:none;background:none;border:1px solid var(--k);padding:6px 10px;cursor:pointer}
.hero{padding:70px 0 40px}.hero h1{font-size:clamp(52px,9vw,150px);font-weight:800}.hero h1 span{font-weight:300}
.hr{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin-top:40px;align-items:end}.hr p{font-size:20px;max-width:44ch;margin:0}
.nums{display:flex;gap:44px;justify-content:flex-end}.nums b{display:block;font-size:44px;font-weight:800;color:var(--k);line-height:1}.nums span{font-size:14px;color:var(--mu)}
.big{margin-top:40px}.big img{width:100%;height:68vh;min-height:420px;object-fit:cover}
section{padding:90px 0}.sh{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:30px;flex-wrap:wrap}.sh h2{font-size:clamp(40px,5.6vw,80px)}
.tabs{display:flex;gap:22px;font-size:15px}.tabs button{background:none;border:0;border-bottom:2px solid transparent;padding:4px 0;font:inherit;cursor:pointer;color:var(--mu)}.tabs button[aria-pressed=true]{color:var(--k);border-color:var(--ac);font-weight:600}
.plist{display:grid;grid-template-columns:1fr 440px;gap:40px}.rows{border-top:1px solid var(--k)}
.row{display:grid;grid-template-columns:60px 1fr 160px 90px;gap:16px;align-items:center;padding:22px 0;border-bottom:1px solid var(--ln);text-decoration:none;cursor:pointer}
.row:hover,.row:focus{background:#E9E7E2}.row .n{color:var(--mu);font-size:14px}.row h3{font-size:clamp(22px,2.4vw,32px);font-weight:600}.row span{color:var(--mu);font-size:15px}
.prev{position:sticky;top:30px;align-self:start}.prev img{width:100%;aspect-ratio:4/5;object-fit:cover;transition:opacity .3s}.prev p{font-size:15px;color:var(--mu);margin:10px 0 0}
.svc{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--k)}.svc div{padding:28px 24px 28px 0;border-right:1px solid var(--ln)}.svc div+div{padding-left:24px}.svc div:last-child{border:0}
.svc h3{font-size:22px;font-weight:600;margin-bottom:10px}.svc p{margin:0;color:var(--mu);font-size:16px}
.aw{list-style:none;padding:0;margin:0;border-top:1px solid var(--k)}.aw li{display:grid;grid-template-columns:100px 1fr auto;gap:20px;padding:16px 0;border-bottom:1px solid var(--ln)}.aw li span{color:var(--mu)}
.ct{background:var(--k);color:#C9C7C1;padding:90px 0}.ct h2{color:#fff;font-size:clamp(44px,7vw,110px)}.ct h2 a{color:var(--ac);text-decoration:none}
.ct .g{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;margin-top:50px;font-size:16px}.ct b{color:#fff;font-weight:600;display:block;margin-bottom:6px}
footer{background:var(--k);color:#77756F;font-size:14px;padding:0 0 30px}.ft{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;border-top:1px solid #333;padding-top:22px}
@media(max-width:980px){.menu{display:none}.burger{display:block}.menu.open{display:flex;flex-direction:column;position:absolute;top:78px;left:0;right:0;background:var(--cn);padding:20px 28px;gap:14px;border-bottom:1px solid var(--ln)}
.hd{position:relative}.hr,.plist{grid-template-columns:1fr}.nums{justify-content:flex-start}.prev{display:none}.svc{grid-template-columns:1fr 1fr}.ct .g{grid-template-columns:1fr}}
@media(max-width:560px){.row{grid-template-columns:40px 1fr}.row span:last-child,.row span:nth-child(3){display:none}.svc{grid-template-columns:1fr}.svc div{padding-left:0!important;border-right:0;border-bottom:1px solid var(--ln)}.aw li{grid-template-columns:1fr}}
.ct h2 a{overflow-wrap:anywhere}.row h3{overflow-wrap:anywhere}

