const P=[["Birchwood Houses","Residential","Oslo, 2026","1600585154340-be6161a56a0c"],["Villa Solstrand","Residential","Mallorca, 2024","1512917774080-9991f1c4c750"],["Harbour Library","Public","Bergen, 2023","1487958449943-2429e8be8625"],["Nordtorget Towers","Commercial","Stockholm, 2025","1486406146926-c627a92ad1ab"],["Fjord School","Public","Ålesund, 2025","1487958449943-2429e8be8625"],["Grønn Office","Commercial","Oslo, 2021","1486406146926-c627a92ad1ab"]];
const $=id=>document.getElementById(id);
function rows(t){$('rows').innerHTML=P.map((p,i)=>[p,i]).filter(([p])=>t==='all'||p[1]===t).map(([p,i],k)=>`<a class="row" href="#" data-i="${i}"><span class="n">${String(k+1).padStart(2,'0')}</span><h3>${p[0]}</h3><span>${p[1]}</span><span>${p[2].split(', ')[1]}</span></a>`).join('')}
$('tabs').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('tabs').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));rows(b.dataset.t)};rows('all');
const prev=e=>{const r=e.target.closest('.row');if(!r)return;const p=P[r.dataset.i];$('pi').src=`https://images.unsplash.com/photo-${p[3]}?w=800&q=75&auto=format&fit=crop`;$('pc').textContent=p[0]+' · '+p[2]};
$('rows').addEventListener('mouseover',prev);$('rows').addEventListener('focusin',prev);
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
